    [FunctionalTheory][InlineData(CollectionGrantAccess.ReadOnly,false)][InlineData(CollectionGrantAccess.ReadWrite,false)][InlineData(CollectionGrantAccess.ReadOnly,true)][InlineData(CollectionGrantAccess.ReadWrite,true)]
    public async Task GivenNativeOldNewAndDirectRecipientRoutes_WhenOwnerMoves_ThenGetAndListRecalculateAndOldOnlySelectionLosesVisibility(CollectionGrantAccess access,bool selected)
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();using var scoped=new ProtectionFixture();using var oldKey=new ProtectionFixture();var o=await Setup(owner);var s=await Setup(client);var from=await Folder(o);var to=await Folder(o);var target=await Create(o,folder:from.PublicId);var (old,oldGrant)=await Share(o,owner,s,client,access,[],[from.Id]);var (next,nextGrant)=await Share(o,owner,s,client,access,[],[to.Id]);var (direct,directGrant)=await Share(o,owner,s,client,access,[target.RecordId],[]);var p=await Profile(s,client,scoped,collections:[old.PublicId,next.PublicId,direct.PublicId]);var oldOnly=await Profile(s,client,oldKey,collections:[old.PublicId]);var oldActor=s with{Access=await Open(s,oldOnly,oldKey)};var actor=selected?s with{Access=await Open(s,p,scoped)}:s;var recipientBefore=await Snapshot(s);var links=await Links(o);var original=await Row(target.RecordId);
        using(var before=await Read(actor,"/api/records/"+target.RecordId)){var data=await Success<RecordDetailsOutput>(before,200);Assert.Contains(old.PublicId,data.CollectionIds);Assert.DoesNotContain(next.PublicId,data.CollectionIds);}using(var response=await Move(o,target.RecordId,destination:to.PublicId))await Moved(original,to,await Success<MoveRecordOutput>(response,200));Assert.Equal(links,await Links(o));Assert.Equal(recipientBefore,await Snapshot(s));using(var after=await Read(actor,"/api/records/"+target.RecordId)){var data=await Success<RecordDetailsOutput>(after,200);Assert.DoesNotContain(old.PublicId,data.CollectionIds);Assert.Contains(next.PublicId,data.CollectionIds);Assert.Contains(direct.PublicId,data.CollectionIds);}using(var list=await Read(actor,"/api/records"))Assert.Contains((await Success<RecordListOutput>(list,200)).Items,x=>x.RecordId==target.RecordId);using(var gone=await Read(oldActor,"/api/records/"+target.RecordId))await Failure(gone,404,"not_found");using(var oldList=await Read(oldActor,"/api/records"))Assert.DoesNotContain((await Success<RecordListOutput>(oldList,200)).Items,x=>x.RecordId==target.RecordId);
    }
