    [FunctionalTheory][InlineData("actor")][InlineData("vaultAccess")][InlineData("recordId")][InlineData("ownerId")][InlineData("profileIds")][InlineData("collectionIds")][InlineData("name")][InlineData("fields")][InlineData("keyWrappers")][InlineData("envelope")][InlineData("editedAt")][InlineData("trashOperationId")][InlineData("deletedAt")][InlineData("purgeAt")][InlineData("unknown")][InlineData("zero")][InlineData("negative")][InlineData("unsafe")][InlineData("missingRevision")][InlineData("missingFolder")][InlineData("duplicateRevision")][InlineData("duplicateFolder")][InlineData("caseRevision")][InlineData("caseFolder")][InlineData("numericString")][InlineData("nullRevision")][InlineData("fraction")][InlineData("overflow")][InlineData("null")][InlineData("array")][InlineData("empty")][InlineData("folderZero")][InlineData("folderBad")][InlineData("folderUppercase")][InlineData("folderCompact")][InlineData("folderNumeric")]
    public async Task GivenStrictOrForgedMoveBody_WhenMoving_Then400WithoutMutation(string kind)
    {
        using var owner=new ProtectionFixture();var s=await Setup(owner);var target=await Create(s);var body=JsonSerializer.SerializeToNode(new{expectedRevision=1,folderId=(Guid?)null},ProtectionFixture.Json)!.AsObject();var fields=new[]{"actor","vaultAccess","recordId","ownerId","profileIds","collectionIds","name","fields","keyWrappers","envelope","editedAt","trashOperationId","deletedAt","purgeAt"};if(fields.Contains(kind))body[kind]=null;if(kind=="unknown")body["secret"]=null;if(kind is "zero" or "negative" or "unsafe")body["expectedRevision"]=kind=="zero"?0:kind=="negative"?-1:9007199254740992;if(kind=="missingRevision")body.Remove("expectedRevision");if(kind=="missingFolder")body.Remove("folderId");if(kind=="caseRevision"){body.Remove("expectedRevision");body["ExpectedRevision"]=1;}if(kind=="caseFolder"){body.Remove("folderId");body["FolderId"]=null;}if(kind=="numericString")body["expectedRevision"]="1";if(kind=="nullRevision")body["expectedRevision"]=null;if(kind=="fraction")body["expectedRevision"]=1.5;if(kind=="overflow")body["expectedRevision"]=9223372036854775808m;if(kind.StartsWith("folder"))body["folderId"]=kind switch{"folderZero"=>Guid.Empty.ToString(),"folderBad"=>"bad","folderUppercase"=>"ABCDEFAB-1234-4321-ABCD-123456789ABC",_=>"abcdefab12344321abcd123456789abc"};if(kind=="folderNumeric")body["folderId"]=1;
        var raw=kind switch{"duplicateRevision"=>"{\"expectedRevision\":1,\"expectedRevision\":1,\"folderId\":null}","duplicateFolder"=>"{\"expectedRevision\":1,\"folderId\":null,\"folderId\":null}","null"=>"null","array"=>"[]","empty"=>"",_=>body.ToJsonString()};var before=await Snapshot(s);using var req=PutFolder(s,"/api/records/"+target.RecordId,Encoding.UTF8.GetBytes(raw));using var r=await Gateway.Client.SendAsync(req);await Failure(r,400);Assert.Equal(before,await Snapshot(s));
    }
